import React from 'react';

const PestMotion = () => (
  <div className="pest-motion" aria-hidden="true">
    <img className="pest pest-termite" src="/termite.svg" alt="" />
    <img className="pest pest-roach" src="/cockroach.svg" alt="" />
    <img className="pest pest-ant" src="/rodent.svg" alt="" />
  </div>
);

export default PestMotion;
